import { type } from "arktype";

export const LooseUser = type({ name: "string" });

export const RejectUser = type({ name: "string" }).onUndeclaredKey("reject");

export const DeleteUser = type({ name: "string" }).onUndeclaredKey("delete");

import { LooseUser, RejectUser, DeleteUser } from "./src/schemas.js";
import { type.errors } from "arktype";

// Test 1: LooseUser({ name: "a", extra: 1 }) must return object where extra === 1
const looseResult = LooseUser({ name: "a", extra: 1 });
console.log("LooseUser with extra key:", looseResult);
if (looseResult instanceof type.errors) {
  console.log("FAIL: LooseUser returned errors:", [...looseResult]);
} else if (looseResult.extra !== 1) {
  console.log("FAIL: LooseUser result.extra !== 1, got:", looseResult.extra);
} else {
  console.log("PASS: LooseUser keeps extra key (extra === 1)");
}

// Test 2: RejectUser({ name: "a", extra: 1 }) must return type.errors
const rejectResult = RejectUser({ name: "a", extra: 1 });
console.log("RejectUser with extra key:", rejectResult);
if (rejectResult instanceof type.errors) {
  console.log("PASS: RejectUser rejects extra key (returned type.errors)");
} else {
  console.log("FAIL: RejectUser did not reject extra key, got:", rejectResult);
}

// Test 3: DeleteUser({ name: "a", extra: 1 }) must return object where "extra" in result === false
const deleteResult = DeleteUser({ name: "a", extra: 1 });
console.log("DeleteUser with extra key:", deleteResult);
if (deleteResult instanceof type.errors) {
  console.log("FAIL: DeleteUser returned errors:", [...deleteResult]);
} else if ("extra" in deleteResult) {
  console.log("FAIL: DeleteUser did not strip extra key, extra still present");
} else {
  console.log("PASS: DeleteUser strips extra key ('extra' in result === false)");
}

// Test 4: All three schemas must accept { name: "a" } without errors
const looseValid = LooseUser({ name: "a" });
const rejectValid = RejectUser({ name: "a" });
const deleteValid = DeleteUser({ name: "a" });
console.log("LooseUser valid input:", looseValid);
console.log("RejectUser valid input:", rejectValid);
console.log("DeleteUser valid input:", deleteValid);

let allValidPass = true;
if (looseValid instanceof type.errors) { console.log("FAIL: LooseUser rejects valid input"); allValidPass = false; }
if (rejectValid instanceof type.errors) { console.log("FAIL: RejectUser rejects valid input"); allValidPass = false; }
if (deleteValid instanceof type.errors) { console.log("FAIL: DeleteUser rejects valid input"); allValidPass = false; }
if (allValidPass) console.log("PASS: All three schemas accept valid input { name: 'a' }");

